mapper.select:
SELECT r.RSRV_ID, r.CONF_RM_ID, rm.CONF_RM_NM, rm.CONF_RM_FLR, rm.CONF_RM_HO, r.RSRV_PURPS, e.EMP_NM AS rsrv_emp_nm, r.BEGIN_DT, r.END_DT, r.All_DAY_YN, r.DEL_YN FROM TB_CONF_RM_RSRV r JOIN TB_CONF_RM rm ON r.CONF_RM_ID = rm.CONF_RM_ID JOIN TB_EMPLOYEE e ON r.RSRV_EMP_ID = e.EMP_ID
AND TRUNC(r.BEGIN_DT) = #{searchDt}
AND rm.CONF_RM_FLR = #{confRmFlr}
AND r.CONF_RM_ID = #{confRmId}
AND e.EMP_NM LIKE '%' || #{rsrvEmpNm} || '%'
AND r.INTG_RSRV_YN = #{intgRsrvYn}
AND rm.USE_YN = #{useYn}
ORDER BY r.BEGIN_DT DESC
